@pytest.mark.asyncio
@pytest.mark.parametrize('change', ['cancel', 'cleanup', 'remove_flow'])
async def test_provider_read_cannot_resurrect_cancelled_or_deleted_flow(managed, monkeypatch, change):
    f = managed
    waiting = await f.auth.authenticate(f.turn(), origin=ORIGIN)
    original = remote_result(f, waiting['request_id'])
    provider_get = f.remote.get_connection
    def racing_get(connection_id):
        result = provider_get(connection_id)
        if change == 'cancel':
            assert f.service.store.cancel(team='TT', owner='UA', source=f.turn().source.to_dict()) == 1
        elif change == 'cleanup':
            f.auth._cleanup(original)
        else:
            with f.service.store.connection() as db:
                db.execute('DELETE FROM kernel_auth_flows WHERE key=?', (original['key'],))
        return result
    monkeypatch.setattr(f.remote, 'get_connection', racing_get)
    with pytest.raises(AccessError):
        f.auth.browser_binding(f.turn())
    assert request(f, waiting['request_id'])['status'] == ('waiting' if change == 'remove_flow' else 'cancelled')
    assert not f.service.store.pending_resumes()
    assert f.auth.account('TT', 'UA', waiting['handle'])['credential_name'] is None
    if change == 'cancel':
        assert flow(f, waiting['request_id'])['state'] == 'pending'
    else:
        assert flow(f, waiting['request_id']) is None


